import ProductCard from "./ProductCard";

function App() {
    const products = [
        { name: "Wireless Headphones", price: "₹2,999", inStock: true },
        { name: "Smart Watch", price: "₹4,999", inStock: false },
        { name: "Bluetooth Speaker", price: "₹1,799", inStock: true },
        { name: "Gaming Mouse", price: "₹999", inStock: true },
        { name: "Laptop Stand", price: "₹1,299", inStock: false },
        { name: "USB-C Hub", price: "₹1,599", inStock: true },
        { name: "Keyboard", price: "₹2,199", inStock: true },
    ];

    return ( <
        div className = "min-h-screen bg-gray-100 p-8" >
        <
        h1 className = "text-3xl font-bold text-center mb-8" >
        Product List <
        /h1>

        <
        div className = "grid grid-cols-1 sm:grid-cols-2 md:grid-cols-3 lg:grid-cols-4 gap-6" > {
            products.map((product, index) => ( <
                ProductCard key = { index }
                name = { product.name }
                price = { product.price }
                inStock = { product.inStock }
                />
            ))
        } <
        /div> <
        /div>
    );
}

export default App;
